"""Panel icons: category header icons and result status icons.

Callers never pick an icon identifier directly. They ask for a category or a
status and splat the returned keyword arguments into ``label()``/``operator()``,
so the source of the icon can change without touching any panel code:

* PNGs from ``png/`` (generated by ``scripts/generate_icons.py``, CC0),
  loaded once at register time into a preview collection;
* the built-in Blender icon when a PNG is missing, the collection is not loaded
  (e.g. during registration) or the user switched the add-on icons off.

``draw()`` code only does dictionary lookups here; nothing is loaded or scanned
while drawing.
"""
from __future__ import annotations

from pathlib import Path

import bpy
import bpy.utils.previews

PNG_DIR = Path(__file__).resolve().parent / "png"

# Built-in icon per LC Workflow category; keys follow constants.PANEL_LABELS
# plus the two panels nested under "Project specific tools".
CATEGORY_ICONS = {
    "scene_info": "INFO",
    "favorites": "SOLO_ON",
    "shape_keys": "SHAPEKEY_DATA",
    "materials": "MATERIAL",
    "substance_designer_baker": "RENDER_STILL",
    "colors": "GROUP_VCOL",
    "uv": "GROUP_UVS",
    "mesh_utilities": "MESH_DATA",
    "quad_reconstruction": "MESH_GRID",
    "cad_reconstruction": "MOD_REMESH",
    "gn_library": "GEOMETRY_NODES",
    "workflow_presets": "PRESET",
    "project_specific_tools": "TOOL_SETTINGS",
    "kalibra_tools": "SHADING_BBOX",
    "babylon_export": "EXPORT",
}

# PNG per category: monochrome glyphs, except a gold Favorites star.
# Scene Info stays a native icon on purpose.
CATEGORY_PNGS = {
    "favorites": "category_favorites",
    "shape_keys": "category_shape_keys",
    "mesh_utilities": "category_mesh",
    "quad_reconstruction": "category_quad",
    "cad_reconstruction": "category_cad",
    "gn_library": "category_gn",
    "materials": "category_materials",
    "colors": "category_colors",
    "uv": "category_uv",
    "substance_designer_baker": "category_bakers",
    "workflow_presets": "category_presets",
    "project_specific_tools": "category_project",
    "kalibra_tools": "category_kalibra",
    "babylon_export": "category_babylon",
}

# Result severity. Each status has its own shape, so meaning never rests on
# color alone; the text next to the icon always states the status as well.
STATUS_ICONS = {
    "ok": "CHECKMARK",
    "warning": "ERROR",
    "error": "CANCEL",
    "info": "INFO",
    "idle": "RADIOBUT_OFF",
    "running": "TIME",
    "cancelled": "PAUSE",
}

_previews = None
_colored = True


def _icon_kwargs(png_name: str | None, builtin: str) -> dict:
    if _colored and _previews is not None and png_name in _previews:
        icon_id = _previews[png_name].icon_id
        if icon_id:
            return {"icon_value": icon_id}
    return {"icon": builtin}


def category_icon(key: str) -> dict:
    """Keyword arguments for the icon of an LC Workflow category."""
    return _icon_kwargs(CATEGORY_PNGS.get(key), CATEGORY_ICONS.get(key, "NONE"))


def status_icon(status: str) -> dict:
    """Keyword arguments for a result status icon (see STATUS_ICONS)."""
    if status not in STATUS_ICONS:
        status = "idle"
    return _icon_kwargs(f"status_{status}", STATUS_ICONS[status])


def draw_header_icon(layout, key: str) -> None:
    """Draw a category icon in a panel header (use from Panel.draw_header)."""
    layout.label(text="", **category_icon(key))


def set_colored(enabled: bool) -> None:
    """Switch between the add-on PNGs and built-in icons (preference update)."""
    global _colored
    _colored = bool(enabled)


def register() -> None:
    """Load the PNGs once. Safe to call again: a previous collection is freed."""
    global _previews
    unregister()
    collection = bpy.utils.previews.new()
    try:
        for path in sorted(PNG_DIR.glob("*.png")):
            collection.load(path.stem, str(path), "IMAGE")
    except Exception:
        bpy.utils.previews.remove(collection)
        raise
    _previews = collection


def unregister() -> None:
    global _previews
    if _previews is not None:
        bpy.utils.previews.remove(_previews)
        _previews = None
